from taf.collectors.core import NamedComponentFactory, StartableCollector
from .cu_static_route_setter import CuStaticRouteSetter
from .vdu_static_route_setter import VduStaticRouteSetter
from ..preparing import Preparing


class CloudUplaneTraceCollector(Preparing,
                                StartableCollector):
    def __init__(self, static_route, cloud_part='cu', **kwargs):
        self.cloud_part = cloud_part
        super(CloudUplaneTraceCollector, self).__init__(**kwargs)
        self.static_route = static_route

    def set_static_route(self):
        if self.cloud_part == 'vdu':
            vdu_static_route_setter = VduStaticRouteSetter(admin_params=self.static_route['admin'])
            vdu_static_route_setter.set_static_route(dest_ip_addr=self.static_route['dest_ip_addr'],
                                                     gateway=self.static_route['gateway'])
        elif self.cloud_part == 'cu':
            cu_static_route_setter = CuStaticRouteSetter(admin_params=self.static_route['admin'])
            cu_static_route_setter.set_static_route(dest_ip_addr=self.static_route['dest_ip_addr'],
                                                    gateway=self.static_route['gateway'])

    def _pre_setup(self):
        self.set_static_route()

    def _post_teardown(self):
        pass


class CloudUplaneTraceCollectorFactory(NamedComponentFactory):
    _product_class = CloudUplaneTraceCollector

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(CloudUplaneTraceCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)

        resulting_arguments["static_route"] = configuration["static_route"]
        resulting_arguments["cloud_part"] = configuration["cloud_part"]
